<?php require_once __DIR__.'/../includes/leave.php';require_login(['admin']);post_guard();$year=(int)($_GET['year']??date('Y'));
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{$emp=(int)$_POST['employee_id'];$tid=(int)$_POST['leave_type_id'];$y=(int)$_POST['year'];$val=(float)$_POST['value'];$mode=$_POST['mode'];$why=trim($_POST['reason']);
  if($why==='')throw new Exception('سبب التعديل مطلوب.');if(!in_array($mode,['set','add','sub'])||$val<0)throw new Exception('قيمة غير صالحة.');
  $pdo->beginTransaction();ensure_balance($emp,$tid,$y);$b=$pdo->prepare('SELECT * FROM leave_balances WHERE employee_id=? AND leave_type_id=? AND year=? FOR UPDATE');$b->execute([$emp,$tid,$y]);$b=$b->fetch();if(!$b)throw new Exception('تعذر العثور على الرصيد.');
  $old=(float)$b['total_days'];$new=$mode==='set'?$val:($mode==='add'?$old+$val:$old-$val);if($new<$b['used_days'])throw new Exception('الإجمالي الجديد أقل من الأيام المستخدمة.');
  $pdo->prepare('UPDATE leave_balances SET total_days=? WHERE id=?')->execute([$new,$b['id']]);
  $pdo->prepare('INSERT INTO leave_balance_adjustments(employee_id,leave_type_id,year,old_total,new_total,reason,admin_user_id) VALUES(?,?,?,?,?,?,?)')->execute([$emp,$tid,$y,$old,$new,$why,$_SESSION['uid']]);
  audit('balance_adjust',"موظف #$emp نوع #$tid سنة $y: $old → $new ($why)");$pdo->commit();flash('تم تعديل الرصيد.');
 }catch(Exception $x){if($pdo->inTransaction())$pdo->rollBack();flash($x->getMessage(),'error');}
 header('Location: balances.php?year='.(int)($_POST['year']??$year));exit;}
$q=trim($_GET['q']??'');$s=$pdo->prepare("SELECT b.*,e.full_name,t.name tn FROM leave_balances b JOIN employees e ON e.id=b.employee_id JOIN leave_types t ON t.id=b.leave_type_id WHERE b.year=? AND (e.full_name LIKE ? OR e.employee_code LIKE ?) ORDER BY e.full_name,t.id LIMIT 200");$s->execute([$year,"%$q%","%$q%"]);$rows=$s->fetchAll();
$emps=$pdo->query("SELECT id,full_name FROM employees WHERE status<>'inactive' ORDER BY full_name")->fetchAll();$types=$pdo->query('SELECT id,name FROM leave_types WHERE is_active=1')->fetchAll();
$log=$pdo->query('SELECT l.*,e.full_name,t.name tn,u.email FROM leave_balance_adjustments l JOIN employees e ON e.id=l.employee_id JOIN leave_types t ON t.id=l.leave_type_id JOIN users u ON u.id=l.admin_user_id ORDER BY l.id DESC LIMIT 15')->fetchAll();
page_start('أرصدة الإجازات');ph('أرصدة الإجازات','متابعة أرصدة الموظفين وتعديلها بسبب موثّق','<button type="button" class="btn" onclick="openModal(\'bm\')">'.ic('plus').'تعديل رصيد</button>');
echo kpis([[count($rows),'أرصدة مطابقة','','','scale'],[array_sum(array_map(fn($r)=>$r['total_days']-$r['used_days'],$rows))+0,'إجمالي المتبقي (أيام)','ok','','sun']]);?>
<form class="card filters" method="get"><div class="search"><?=ic('search')?><input name="q" placeholder="بحث عن موظف" value="<?=e($q)?>" aria-label="بحث"></div><label>السنة<input type="number" name="year" value="<?=$year?>"></label><button class="btn">بحث</button></form>
<?php modal_open('bm','تعديل رصيد إجازة',['form'=>'method="post"','wide'=>true,'grid'=>true,'desc'=>'كل تعديل يُسجَّل مع السبب في سجل التعديلات.']);?><input type="hidden" name="csrf" value="<?=csrf()?>"><label>الموظف<select name="employee_id"><?php foreach($emps as $x)echo '<option value="'.$x['id'].'">'.e($x['full_name']).'</option>';?></select></label>
<label>النوع<select name="leave_type_id"><?php foreach($types as $x)echo '<option value="'.$x['id'].'">'.e($x['name']).'</option>';?></select></label><label>السنة<input type="number" name="year" value="<?=$year?>"></label>
<label>العملية<select name="mode"><option value="set">تعيين الإجمالي</option><option value="add">إضافة رصيد</option><option value="sub">خصم رصيد</option></select></label><label>القيمة (أيام)<input type="number" step="0.5" min="0" name="value" required></label><label>السبب<input name="reason" required></label><div class="full preview" id="bpv"></div>
<?php modal_close('<button class="btn">تطبيق</button><button type="button" class="btn ghost" data-close>إلغاء</button>',true);?>
<div class="card tbl"><?=card_h('الأرصدة','سنة '.$year)?><table><tr><th>الموظف</th><th>النوع</th><th>الإجمالي</th><th>المستخدم</th><th>المتبقي</th><th></th></tr><?php foreach($rows as $r):?><tr><td class="cmain"><b><?=e($r['full_name'])?></b></td><td><?=e($r['tn'])?></td><td><?=$r['total_days']+0?></td><td><?=$r['used_days']+0?></td><td><b><?=$r['total_days']-$r['used_days']?></b></td><td class="act"><button type="button" class="btn ghost sm" onclick="bal(<?=(int)$r['employee_id']?>,<?=(int)$r['leave_type_id']?>)"><?=ic('pencil')?>تعديل</button></td></tr><?php endforeach;if(!$rows)echo empty_row(6,'لا توجد أرصدة لهذه السنة','جرّب سنة أخرى أو غيّر البحث.','scale');?></table></div>
<div class="card tbl"><?=card_h('آخر التعديلات اليدوية')?><table><tr><th>الموظف</th><th>النوع</th><th>القديم</th><th>الجديد</th><th>السبب</th><th>بواسطة</th><th>الوقت</th></tr><?php foreach($log as $l):?><tr><td class="cmain"><b><?=e($l['full_name'])?></b></td><td><?=e($l['tn'])?></td><td><?=$l['old_total']+0?></td><td><?=$l['new_total']+0?></td><td class="wrap"><?=e($l['reason'])?></td><td><?=e($l['email'])?></td><td><?=e($l['created_at'])?></td></tr><?php endforeach;if(!$log)echo empty_row(7,'لا توجد تعديلات يدوية','','list');?></table></div>
<script>(function(){const M=<?=json_encode((object)array_reduce($rows,function($c,$r){$c[$r['employee_id'].'|'.$r['leave_type_id']]=['t'=>(float)$r['total_days'],'u'=>(float)$r['used_days']];return $c;},[]))?>,f=document.querySelector("#bm form"),o=document.getElementById("bpv");
function pv(){const m=M[f.employee_id.value+"|"+f.leave_type_id.value],v=parseFloat(f.value.value)||0;if(!m){o.textContent="الرصيد الحالي: — (يُنشأ تلقائيًا عند الحفظ). الخادم هو المرجع النهائي.";return;}
const n=f.mode.value==="set"?v:(f.mode.value==="add"?m.t+v:m.t-v);o.textContent="الرصيد الحالي (الإجمالي): "+m.t+" · المستخدم: "+m.u+" · الإجمالي بعد العملية: "+n+" · المتبقي بعدها: "+(n-m.u)+(n<m.u?" — تنبيه: أقل من المستخدم وسيرفضه الخادم":"");}
["employee_id","leave_type_id","mode","value"].forEach(k=>f[k].addEventListener("input",pv));window.bal=function(e,t){f.employee_id.value=e;f.leave_type_id.value=t;pv();openModal("bm");};pv();})();</script>
<?php page_end();
